    'message-changed',
    'run-agents',
    'search-files',
    'preview-file',
  ],
  data() {
    return {
      showEventsPanel: false,
      activeMessageData: null,
      expandedId: null,
      messageElRefs: [],
      scrollContainerEl: null,
    }
  },
