      const allProfileNames = this.profiles.map(p => p.name)
      const mentionedNames = [...this.editorText?.matchAll(/@([^\s]+)/mg) || []].map(m => m[1])
      return mentionedNames.some(name => allProfileNames.includes(name))
    }
  },
  watch: {
